import data from "./simulation-data.json";

// The published pool simulation (packages/sim/results/<date>/). The JSON is generated by scripts/sync-simulation.mjs and
// simulation.test.ts re-derives it from that folder. Nothing here is typed by hand. Every figure follows from assumptions;
// none is measured.

export const SIM = data;
export type SimScenario = (typeof data.scenarios)[number];

const n0 = (v: number) => Math.round(v).toLocaleString("en-US");
export const pct = (v: number, d = 1) => `${(v * 100).toFixed(d)}%`;

export const probabilityText = (s: SimScenario) =>
  `${pct(s.pInsolvency.p)} (${pct(s.pInsolvency.lo)} to ${pct(s.pInsolvency.hi)})`;

/** A solvent scenario is "not insolvent within N days", never "never": the runs only cover N days. */
export const timeToInsolvencyText = (s: SimScenario, days = SIM.days) =>
  s.timeToInsolvencyDays.insolventRuns === 0
    ? `not insolvent within ${days} days`
    : `${s.timeToInsolvencyDays.median} (${n0(s.timeToInsolvencyDays.insolventRuns)} runs)`;

export type Measure = { label: string; value: (s: SimScenario) => string };

/** The six measures the plan names (R42), one row each. */
export const MEASURES: Measure[] = [
  { label: "Chance the pool is insolvent, 95% interval", value: probabilityText },
  { label: "Ending capital, median (5th to 95th), NEAR", value: (s) => `${n0(s.endingCapitalNear.median)} (${n0(s.endingCapitalNear.p5)} to ${n0(s.endingCapitalNear.p95)})` },
  { label: "Claims paid, median, NEAR", value: (s) => n0(s.claimsPaidNear.median) },
  { label: "Most owed and unpaid at once, median (95th), NEAR", value: (s) => `${n0(s.peakUnpaidNear.median)} (${n0(s.peakUnpaidNear.p95)})` },
  { label: "Solvency ratio, median (5th)", value: (s) => `${s.solvencyRatio.median.toFixed(2)} (${s.solvencyRatio.p5.toFixed(2)})` },
  { label: "Time to insolvency, median days", value: (s) => timeToInsolvencyText(s) },
];

export const rulesText = (s: SimScenario) =>
  s.adequacyOn && s.concentrationOn ? "on" : "off: no adequacy rule or concentration limit";

export const eventText = (s: SimScenario) =>
  s.scripted.length === 0
    ? "none scripted"
    : s.scripted.map((e) => `day ${e.day}, ${e.kind === "most_concentrated_authority" ? "the authority with most coverage behind it changes everything it controls" : "the most exposed implementation changes"}`).join("; ");

export const withdrawalText = (s: SimScenario) =>
  s.withdrawal ? `day ${s.withdrawal.day}, ${s.withdrawal.shareBps / 100}% of free capital${s.lockEnforced ? "" : ", lock switched off"}` : "none";

export const peopleText = () => `${SIM.agents} agents, ${SIM.days} days, ${SIM.runsPerScenario.toLocaleString("en-US")} seeded runs per scenario (seeds ${SIM.firstSeed} to ${SIM.firstSeed + SIM.runsPerScenario - 1})`;
